        serif;
}

.root {
    display: flex;
    flex-direction: column;

    .header,
    .controls {
        background: #f8f8f8;
    }

    .header {
        padding: 32px;
        border-bottom: 1px solid black;
        display: flex;
        flex-direction: row;
        justify-content: center;
        align-items: center;

        .progress-bar {
            width: 300px;
            height: 24px;
            border: 1px solid #999;
            border-radius: 12px;
            background: white;
            overflow: hidden;

            .progress-fill {
                height: 100%;
                background: palegreen;
            }
        }
    }

    .card-container {
        flex: 1;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        background: #fcfcfc;
        overflow: hidden;

        .card {
            background: white;
            display: flex;
            flex-direction: column;

            .card-header {
                border-bottom: 1px solid black;
                padding: 24px;

                h1 {
                    font-size: 36px;
                }
            }

            .card-content {
                flex: 1;
                display: flex;
                flex-direction: column;
                overflow-x: hidden;
                overflow-y: auto;

                .question,
                .answer,
                .prompt {
                    padding: 24px;
                }

                .question {
                    border-bottom: 1px solid black;
                }

                .answer {
                    min-height: 30px;
                }

                .rich-text {
                    font-size: 30px;
                    text-align: justify;
                    line-height: 1.4;

                    .cloze {
                        width: 30px;
                        background: #a0a0a0;
                        text-decoration: none;
                        border-radius: 8px;
                        color: transparent;
                    }

                    .cloze-reveal {
                        color: royalblue;
                    }

                    img {
                        display: block;
                        margin-left: auto;
                        margin-right: auto;
                        max-width: 100%;
                        height: auto;
                    }

                    ul,
                    ol {
                        padding-left: 24px;
                    }

                    p,
                    img,
                    ol,
                    ul,
                    blockquote,
                    table,
                    pre {
                        &:not(:last-child) {
                            margin-bottom: 16px;
                        }
                    }

                    blockquote {
                        background: #f7f7f7;
