/workspace/static/style.css.content:
* {
    margin: 0;
    padding: 0;
    font-weight: normal;
}

*,
*::before,
*::after {
    box-sizing: border-box;
}

html,
body,
.root {
    width: 100vw;
    height: 100vh;
}

body {
    font-family:
        "TeX Gyre Termes", "Nimbus Roman No9 L", "Times New Roman", "Times",
        serif;
}

.root {
    display: flex;
    flex-direction: column;
}

.root .header,
.root .controls {
    background: #f8f8f8;
}

.root .header {
    padding: 32px;
    border-bottom: 1px solid black;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
}

.root .header .progress-bar {
    width: 300px;
    height: 24px;
    border: 1px solid #999;
    border-radius: 12px;
    background: white;
    overflow: hidden;
}

.root .header .progress-bar .progress-fill {
    height: 100%;
    background: palegreen;
}

.root .card-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    background: #fcfcfc;
    overflow: hidden;
}

.root .card-container .card {
    background: white;
    display: flex;
    flex-direction: column;
}

.root .card-container .card .card-header {
    border-bottom: 1px solid black;
    padding: 24px;
}

.root .card-container .card .card-header h1 {
    font-size: 36px;
}

.root .card-container .card .card-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow-x: hidden;
    overflow-y: auto;
}

.root .card-container .card .card-content .question,
.root .card-container .card .card-content .answer,
.root .card-container .card .card-content .prompt {
    padding: 24px;
}

.root .card-container .card .card-content .question {
    border-bottom: 1px solid black;
}

.root .card-container .card .card-content .answer {
    min-height: 30px;
}

.root .card-container .card .card-content .rich-text {
    font-size: 30px;
    text-align: justify;
    line-height: 1.4;
}

.root .card-container .card .card-content .rich-text .cloze {
    width: 30px;
    background: #a0a0a0;
    text-decoration: none;
    border-radius: 8px;
    color: transparent;
}

.root .card-container .card .card-content .rich-text .cloze-reveal {
    color: royalblue;
}

.root .card-container .card .card-content .rich-text img {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: 100%;
    height: auto;
}

.root .card-container .card .card-content .rich-text ul,
.root .card-container .card .card-content .rich-text ol {
    padding-left: 24px;
}

.root .card-container .card .card-content .rich-text p:not(:last-child),
.root .card-container .card .card-content .rich-text img:not(:last-child),
.root .card-container .card .card-content .rich-text ol:not(:last-child),
.root .card-container .card .card-content .rich-text ul:not(:last-child),
.root .card-container .card .card-content .rich-text blockquote:not(:last-child),
.root .card-container .card .card-content .rich-text table:not(:last-child),
.root .card-container .card .card-content .rich-text pre:not(:last-child) {
    margin-bottom: 16px;
}

.root .card-container .card .card-content .rich-text blockquote {
    background: #f7f7f7;
    border-left: 4px solid #ccc;
    padding: 8px 12px;
}

.root .card-container .card .card-content .rich-text table {
    border-collapse: collapse;
    width: 100%;
    font-size: 0.65em;
    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Helvetica,
        Arial,
        sans-serif;
    line-height: 1.6;
    border: 1px solid #999;
}

.root .card-container .card .card-content .rich-text table th,
.root .card-container .card .card-content .rich-text table td {
    border: 1px solid #bbb;
    padding: 10px 14px;
    text-align: left;
    vertical-align: top;
}

.root .card-container .card .card-content .rich-text table th {
    background: #e8e8e8;
    font-weight: 600;
    border: 1px solid #999;
}

.root .card-container .card .card-content .rich-text table tbody tr:nth-child(odd) {
    background: #ffffff;
}

.root .card-container .card .card-content .rich-text table tbody tr:nth-child(even) {
    background: #f5f5f5;
}

.root .card-container .card .card-content .rich-text table code {
    font-size: 0.85em;
    background: #ececec;
}

.root .card-container .card .card-content .rich-text code {
    background: #f7f7f7;
    border: 1px solid #ddd;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: "Menlo", "Monaco", "Courier New", monospace;
    font-size: 0.7em;
    color: inherit;
}

.root .card-container .card .card-content .rich-text pre {
    background: #f7f7f7;
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 12px;
    overflow-x: auto;
    font-size: 0.7em;
    line-height: 1.5;
}

.root .card-container .card .card-content .rich-text pre code {
    background: transparent;
    border: none;
    padding: 0;
    border-radius: 0;
    font-size: 0.85em;
    color: inherit;
}

.root .card-container .card .card-content .rich-text audio {
    width: 100%;
}

.root .card-container .card .card-content .rich-text .katex {
    font-size: 1em;
}

.root .controls {
    border-top: 1px solid black;
}

.root .controls form {
    display: flex;
    justify-content: space-between;
}

.root .controls form .spacer {
    flex: 1;
}

.root .controls form input {
    -webkit-appearance: none;
    appearance: none;
    background: white;
    border: 1px solid #999;
    padding: 7px 12px;
    font-size: 16px;
    color: black;
    font-family:
        system-ui,
        -apple-system,
        "Helvetica Neue",
        sans-serif;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    box-shadow: #ccc 0 1px 3px 0;
}

.root .controls form input:disabled {
    cursor: not-allowed;
}

.finished h1 {
    text-align: center;
}

.finished .summary {
    font-size: 24px;
    margin-bottom: 48px;
}

.finished h2 {
    border-bottom: 1px solid #ccc;
}

.finished .stats table {
    width: 100%;
    border-collapse: collapse;
}

.finished .stats table tr {
    border-bottom: 1px solid #eee;
}

.finished .stats table tr td {
    padding-top: 12px;
    padding-bottom: 12px;
}

.finished .stats table tr td.key {
    font-family: "SF Pro", sans-serif;
    font-weight: 500;
    width: auto;
    white-space: nowrap;
}

.finished .stats table tr td.val {
    font-family: "SF Pro", sans-serif;
    font-feature-settings: "tnum";
    font-variant-numeric: tabular-nums;
    width: 100%;
}

.finished .shutdown-container {
    margin-top: 48px;
    text-align: center;
}

.finished .shutdown-container form {
    display: inline-block;
}

.finished .shutdown-container .shutdown-button {
    background: #dc3545;
    color: white;
    border: 1px solid #c82333;
    padding: 12px 24px;
    font-size: 18px;
    font-family:
        system-ui,
        -apple-system,
        "Helvetica Neue",
        sans-serif;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    box-shadow: rgba(220, 53, 69, 0.3) 0 2px 8px 0;
    transition:
        background-color 0.2s,
        box-shadow 0.2s;
}

.finished .shutdown-container .shutdown-button:hover {
    background: #c82333;
    box-shadow: rgba(220, 53, 69, 0.5) 0 4px 12px 0;
}

.finished .shutdown-container .shutdown-button:active {
    background: #bd2130;
    box-shadow: rgba(220, 53, 69, 0.2) 0 1px 4px 0;
}

@media (max-width: 768px) {
    .card {
        width: 100%;
        height: 100%;
        box-shadow: none;
    }

    .controls {
        padding: 12px;
    }

    .controls form {
        flex-direction: column;
    }

    .controls form input {
        margin: 6px 0;
    }

    .controls form .grades {
        display: flex;
        flex-direction: row;
        justify-content: space-between;
    }

    .finished {
        padding: 24px;
    }

    .finished h1 {
        font-size: 36px;
        margin-bottom: 36px;
    }

    .finished h2 {
        font-size: 30px;
        margin-bottom: 16px;
    }

    .finished .stats {
        font-size: 16px;
    }

    .finished .val {
        padding-left: 24px;
    }
}

@media (min-width: 769px) {
    .card {
        width: 900px;
        min-height: 400px;
        max-height: 90%;
        box-shadow: 0 0 48px 16px #ddd;
        border: 1px solid black;
    }

    .controls {
        padding: 32px;
    }

    .controls form {
        flex-direction: row;
    }

    .controls form input {
        margin: 0 12px;
    }

    .finished {
        padding: 48px;
    }

    .finished h1 {
        font-size: 48px;
        margin-bottom: 48px;
    }

    .finished h2 {
        font-size: 36px;
        margin-bottom: 24px;
    }

    .finished .stats {
        font-size: 22px;
    }

    .finished .val {
        padding-left: 48px;
    }
}

